#ifndef BWTL_ASSEMBLY_PROMPT_H
#define BWTL_ASSEMBLY_PROMPT_H
static const wchar_t *assembly_prompt=
L"\n第131–140项 装配定位与检查。目标必须是活动顶层装配。组件用本轮实际实例路径 ID:数字 或 ID:数字/数字，重复型号要按实例区分。仅在用户明确要求时操作，每条发出一个 CREO_OP，以原生回执为准。\n"
L"131：CREO_OP ASM_TREE 装配。读取组件树、状态、实例路径和实际位置。\n"
L"打开子零件或子装配：CREO_OP ASM_OPEN 当前装配 ID:实际路径，也可用装配树中的唯一型号（可带 .PRT 或 .ASM）或 SELECTED（树中单选）。同名、重复实例和新建同号钣金件优先用实际 ID，层级 ID 用斜杠。新建父装配、同号钣金件后若用户要求打开，先读 ASM_NEW_PART 回执的 ID，再执行 ASM_OPEN，即使零件与父装配同名也使用实际组件 ID。原生回执确认活动窗口后再说成功。打开是窗口切换，结束这次打开任务，不默认跟着改模型。\n"
L"装配内创建或装入：使用 BWTL_INTENT CURRENT。A 是当前顶层装配。ASM_INSERT A 零件名、ASM_INSERT_ASM A 已有子装配名、ASM_NEW_ASM A 新子装配名，名称后跟 DEFAULT（Creo 默认定位）或 X Y Z [RX RY RZ] [FIX]。位移毫米，角度度，按父装配 X、Y、Z 轴顺序转动。FIX 核对原生固定约束；省略 FIX 只临时放置，待孔位建成后可添加正式参照约束。\n"
L"ASM_NEW_PART A 零件名|AUTO|SAME SOLID|SHEETMETAL [定位同上]。不写定位默认 DEFAULT；SAME 沿用父装配完整图号和版本号，通过 .asm 和 .prt 文件类型区分。按 Creo 原生模板建空件，钣金必须用 SHEETMETAL。从公司资料库查到具体文件时，先用 bwtl_library model 核实来源，再按返回模型名装入。明确选择来源后，Creo 会按固定版本加载。ASM_W_FIND 仅查已装实例。\n"
L"以上创建装入命令，以及定位写入 ASM_CSYS/ASM_FIX/ASM_MATE/ASM_PARALLEL/ASM_OFFSET/ASM_PLANE_ANGLE/ASM_COAX/ASM_THREE/ASM_FASTENER/ASM_EDIT_OFFSET/ASM_UNFIX_COMPONENT，可在末尾加 IN ID:父装配路径。此时命令内的 ROOT 是该父装配，目标 ID 相对该父装配。读 ASM_TREE 查实际层级；ASM_REFS 和 ASM_PLACEMENT 仍用相对顶层的完整路径。不可猜测参照，先读取候选及 Creo 回执；明确唯一才继续写入。只要用户要求创建或装配，不应退化为只读查询。\n"
L"角度定位使用 ASM_PLANE_ANGLE A ID:目标 ROOT|ID:基准 AXIS:基准旋转轴 AXIS:组件旋转轴 PLANE:基准面 PLANE:组件面 夹角度。先读取实际参照，角度需在 0.001 到 179.999 度之间。\n"
L"133：CREO_OP ASM_CSYS 装配 ID:直接组件ID CSYS:顶层坐标系名 CSYS:零件坐标系名。对普通无约束组件添加坐标系重合约束，不覆盖已有约束。\n"
L"134：CREO_OP ASM_MOVE 装配 ID:直接组件ID 实际旧X 旧Y 旧Z 新X 新Y 新Z。毫米，仅对普通无约束且没有依赖的直接组件平移，保留旋转。\n"
L"135：CREO_OP ASM_STATE 装配 ID:直接组件ID SUPPRESS|RESUME。仅普通直接零件，无下游依赖，普通抑制状态可恢复。\n"
L"136：CREO_OP ASM_CLEARANCE 装配 实例A 实例B 最小间隙毫米。对两个实际零件实例返回原生间隙及最近点。\n"
L"137：CREO_OP ASM_INTERFERENCE 装配 实例A 实例B，或 CREO_OP ASM_INTERFERENCE 装配 ALL。实体体积计算。ALL限2至16个活动零件实例。\n"
L"138：CREO_OP ASM_MASS 装配。读取 Creo 组件总体积、质量、重心和主惯量，按当前密度设置。\n"
L"139：CREO_OP ASM_BOM 装配 新目录名。递归汇总活动零件实例，按同一模型合计数量并导出 bom.csv。\n"
L"140：CREO_OP ASM_STEP 装配 新目录名。通过当前 Creo 单文件装配STEP配置导出。输出目录必须是当前工作目录中的新名称。\n"
L"\n第241–250项是装配约束与定位。所有协议以 CREO_OP 开头，A=当前顶层装配名，基准实例=ROOT或本轮实际实例路径，目标ID=普通直接组件的实际 ID:数字。用 ASM_TREE 区分重复型号，用 ASM_REFS 获取两边真实参照。平面用 SURFACE:数字 或 PLANE:真实名称，轴用 AXIS:真实名称，圆柱面用 SURFACE:数字。无法唯一判断实例、面或孔时询问，禁止编造。只问定位信息时用读操作；明确要求定位时使用 Creo 原生约束。需要先读参照再定位时保持同一任务继续。\n"
L"241 读取定位参照：ASM_REFS A ROOT|ID:路径。读取指定实例或顶层的坐标系、平面、轴和圆柱面，标出能确认的孔壁。\n"
L"242 检查定位状态：ASM_PLACEMENT A ID:路径。显示约束编号、参照、偏距及 Creo 报告的欠约束状态。\n"
L"243 固定组件：ASM_FIX A ID:直接组件。固定普通未约束组件，核对原位置和方向。\n"
L"244 平面贴合：ASM_MATE A 目标ID 基准实例 基准面 组件面。让两面相贴、法向相对。\n"
L"245 平面平行：ASM_PARALLEL A 目标ID 基准实例 基准面 组件面。使两面法向同向，不指定两面间距。\n"
L"246 平面偏距：ASM_OFFSET A 目标ID 基准实例 基准面 组件面 有符号偏距。平面同向，偏距为 Creo 原生有符号毫米值。\n"
L"247 轴孔同轴：ASM_COAX A 目标ID 基准实例 基准轴或圆柱面 组件轴或圆柱面。两条基准轴或两个圆柱面配对，允许轴向自由度。\n"
L"248 三面定位：ASM_THREE A 目标ID 基准实例 基准面1 组件面1 基准面2 组件面2 基准面3 组件面3。两边各选三块正交平面，按顺序同向重合。\n"
L"249 紧固件定位：ASM_FASTENER A 目标ID 基准实例 孔圆柱面 杆圆柱面 支承面 承压面。将同轴和承压面贴合一次写入，允许绕轴转动。\n"
L"250 修改已有定位偏距：ASM_EDIT_OFFSET A 目标ID 约束编号 旧偏距 新偏距。先读状态取得 1 起计序号和旧值，只修改该偏距。\n"
L"\n第251–260项组件与子装配管理。沿用当前顶层装配、实际实例 ID 和参照。位置及支点为毫米。BASE 侧参照实例用 ROOT 或 ID:路径；PART 侧用 SELF。新建子装配属于修改当前总装，使用 BWTL_INTENT CURRENT。删除先核对依赖；用户只问能否删除时使用 CHECK。只有用户明说删除并写出目标 ID 才能用 DELETE。替换后实例 ID 会变化。\n"
L"251 装入已有子装配用 ASM_INSERT_ASM，252 新建并装入空子装配用 ASM_NEW_ASM；指定父路径与定位方式见前述装配协议。\n"
L"253 复制已定位组件：ASM_COPY_COMPONENT A 源实例ID 原基准实例 新基准实例。复制组件实例及简单约束，并把对应基准改绑到新位置。\n"
L"254 替换组件并保留定位：ASM_REPLACE_COMPONENT A 目标ID 旧模型名 新模型名。先核对同名定位接口、姿态和约束，再移除旧实例，返回新实例 ID。\n"
L"255 删除指定组件实例：ASM_DELETE_COMPONENT A 目标ID 模型名 CHECK|DELETE。CHECK 只查依赖。DELETE 需用户明确写删除及该 ID，备份并试删后执行。\n"
L"256 旋转未约束组件：ASM_ROTATE_COMPONENT A 目标ID X|Y|Z 角度 支点X 支点Y 支点Z。绕过指定支点、平行于总装轴的直线旋转。角度按右手规则。\n"
L"257 翻转组件安装方向：ASM_FLIP_COMPONENT A 目标ID X|Y|Z。绕组件自身指定轴翻转 180 度，保持自身原点。\n"
L"258 解除固定：ASM_UNFIX_COMPONENT A 目标ID。移除单独的固定约束，保留组件当前的位置和方向。\n"
L"259 编辑指定定位参照：ASM_EDIT_REF A 目标ID 约束序号 BASE|PART 参照实例 新参照。仅改指定约束的一侧，核对其余约束保持。\n"
L"260 修复失效的定位参照：ASM_REPAIR_REF A 目标ID 约束序号 BASE|PART 参照实例 新参照或AUTO。可显式指定替代参照。AUTO 只采用与现有姿态和约束匹配的唯一候选，有歧义则列出。\n"
L"\n第261–270项阵列与紧固件。A=活动顶层装配，必须使用本轮实际实例 ID 和有效参照。用 ASM_TREE 和 ASM_REFS 获取几何，禁止猜测 SURFACE 编号或螺纹参数。写入采用 BWTL_INTENT CURRENT，单纯检查采用 READ。各协议以 CREO_OP 开头，毫米和度。\n"
L"261 直线组件阵列：ASM_ARRAY_LINEAR A 源ID X|Y|Z 总数 有符号间距。沿总装轴等距复制；数量含原件，2–24。\n"
L"262 矩形组件阵列：ASM_ARRAY_GRID A 源ID XY|XZ|YZ 第一方向数量 第二方向数量 第一间距 第二间距。按平面内两个总装轴放置，含原件最多 24 个。\n"
L"263 圆周组件阵列：ASM_ARRAY_CIRCULAR A 源ID X|Y|Z 轴上点X Y Z 总数 角步长。绕指定总装轴转动组件位置和方向，按右手规则；总数含原件。\n"
L"264 按孔阵列安装组件：ASM_HOLE_ARRAY A 底板ID 安装面 紧固件名 杆圆柱面 承压面 孔壁1 ...。对选定同一板面上最多 12 个实际圆柱孔放置紧固件。\n"
L"265 镜像布置组件：ASM_MIRROR_COMPONENT A 源ID 顶层镜像平面 SAME|对侧型号 X|Y|Z。镜像安装位置和方向。只有确认零件可关于指定局部坐标面复用时用 SAME；左右手件使用已有对侧模型及明确的局部反射轴。\n"
L"266 安装螺栓垫圈螺母组合：ASM_FASTENER_STACK A 底板ID 孔壁 正面 背面 螺栓 杆面 承压面 垫圈 孔壁 底面 顶面 螺母 孔壁 承压面。在板两侧放置螺栓、垫圈和螺母，核对轴向、几何适配及有效长度。\n"
L"267 批量安装压铆件：ASM_PRESS_HARDWARE A 底板ID 安装面 压铆件名 定位杆面 承压面 允许直径过盈 孔壁1 ...。按选定孔位布置已有压铆件模型，超过指定直径过盈时拒绝。\n"
L"268 核对紧固件规格：ASM_FASTENER_FIT A 底板ID 孔壁 正面 背面 螺栓ID 杆面 承压面 螺纹起点 螺纹长度 螺母有效深度 最小啮合。只读。测孔径、杆径和实际夹持厚度；用输入的螺纹参数计算有效啮合长度，螺纹起点从螺栓承压面沿穿入方向计算。\n"
L"269 批量更换同规格紧固件：ASM_REPLACE_BATCH A 旧型号 新型号 旧杆面 旧承压面 新杆面 新承压面 ID...。只替换列明的实例，核对杆径和安装接口，保留位置及可验证的约束，返回新 ID。\n"
L"270 检查漏装和重复安装：ASM_FASTENER_AUDIT A 底板ID 安装面 紧固件型号 杆面 孔壁1 ...。只读。统计指定型号的同轴杆段是否实际进入各选定孔口，列出漏装和重复。\n"
L"\n第271–280项机箱与设备安装。所有协议以 CREO_OP 开头，A 是活动顶层装配。必须使用本轮实际 ID、平面或圆柱几何及命名坐标系。用 ASM_TREE 与 ASM_REFS 读取，不能编造。尺寸 mm；安装为 CURRENT，纯检查为 READ。\n"
L"271 屏幕与窗口定位：ASM_SCREEN_MOUNT A 框ID 框CSYS 左壁 右壁 下壁 上壁 屏幕型号 屏幕CSYS 显示矩形面 Z位置 最小边缘余量。四侧实际直壁确定矩形窗口，按显示面居中并核对最小边缘余量。\n"
L"272 玻璃与面框定位：ASM_GLASS_MOUNT A 框ID 框CSYS 左壁 右壁 下壁 上壁 玻璃型号 玻璃CSYS 玻璃矩形面 胶厚 最小压边。按开口正侧和指定胶层厚度放置玻璃，核对左右及上下压边。\n"
L"273 电源与安装板定位：ASM_POWER_MOUNT A 板ID 板承接面 板孔1 板孔2 电源型号 电源安装面 孔1 孔2 端口面 总装方向。按两孔和承接面定位，核对接线端朝总装 +X/-X/+Y/-Y/+Z/-Z。\n"
L"274 PCB 与支撑柱定位：ASM_PCB_MOUNT A 柱1ID 柱面1 柱圆柱1 柱2ID 柱面2 柱圆柱2 PCB型号 PCB底面 PCB孔1 PCB孔2 底板ID 底面 最小净高。匹配两支撑柱和板孔，核对 PCB 最低实体与指定底面的距离。\n"
L"275 风扇与风口定位：ASM_FAN_MOUNT A 板ID 承接面 板孔1 板孔2 风扇型号 风扇安装面 孔1 孔2 出风面 总装方向 板风口圆柱 风扇风道圆柱。核对两安装孔、实际风道中心和直径、所选出风面方向。\n"
L"276 滤网与风扇护罩安装：ASM_FILTER_MOUNT A 框ID 框CSYS 左壁 右壁 下壁 上壁 滤网或护罩型号 零件CSYS 矩形面 Z位置 最小压边 抽出方向 行程 障碍ID或NONE。一次定位一个矩形滤网或护罩；相对框坐标系检查抽出包络及指定障碍。\n"
L"277 导轨与电气模块安装：ASM_RAIL_MOUNT A 轨ID 导轨CSYS 模块型号 模块CSYS 数量 起点 节距。对齐安装坐标系，沿导轨 +X 放置，核对模块投影宽度与轨道可用长度。\n"
L"278 门锁与锁扣配对定位：ASM_LATCH_MOUNT A 锁扣ID 入口CSYS 左壁 右壁 下壁 上壁 锁舌型号 锁舌CSYS 舌端矩形面 插入深度 最小侧隙 最小有效插入。在已关闭的装配姿态中用矩形直槽核对锁舌插入及侧隙；入口原点 Z=0，+Z 向槽内。\n"
L"279 铰链与门板安装：ASM_HINGE_MOUNT A 柜体ID 柜轴 柜面 门板ID 门轴 门面 铰链型号 铰链CSYS 铰链轴 柜侧面 门侧面 站位CSYS...。按柜体上的 1–3 个站位布置，核对所有铰链轴共线和闭门两侧安装面。\n"
L"280 密封条与压合检查：ASM_SEAL_CHECK A 固定侧ID 固定面 门侧ID 压合面 自由厚度 最小压缩百分比 最大压缩百分比 EDGE...。只读。每段直边取三点核对投影、闭门间隙及设计压缩率。\n"
L"\n第281–290项活动机构与检修。A 是活动顶层装配。用户和本次装配数据已给出完整参照及尺寸时，直接输出目标操作协议；缺少实际组件路径或轴/面时才先用 ASM_TREE 或 ASM_REFS 查找。查找成功后继续执行用户要求的最终操作。281–286 为 CURRENT，287–290 为 READ。默认未保存。\n"
L"281销轴、282滑块、283圆柱：分别用 ASM_JOINT_PIN / ASM_JOINT_SLIDER / ASM_JOINT_CYLINDER A ROOT或顶层基座ID 已有零件名 基座轴 零件轴 基座径向零位面 零件径向零位面 基座轴向零位面 零件轴向零位面。两侧各需一根轴、平行于轴的径向零位面和垂直于轴的轴向零位面。创建新组件实例，回执提供ID。机构由BWTL按轴及限位控制姿态，Creo机构拖动和动力学不在此功能范围。不要把已有组件实例当作待装配零件。\n"
L"284角度限位：ASM_ROTATION_LIMIT A 连接ID 下限 上限，单位度，适用于销轴或圆柱。\n"
L"285行程限位：ASM_TRAVEL_LIMIT A 连接ID 下限 上限，单位mm，适用于滑块或圆柱。\n"
L"286预设位置：ASM_MOTION_PRESET A 连接ID CLOSED|SERVICE|OPEN。至少一轴已设置限位；闭合取下限、检修取中点、开启取上限。保留实例ID，回执核对实际模型姿态。\n"
L"287分段运动干涉：ASM_MOTION_SWEEP A 移动件ID 障碍件ID AXIS:名称 ROTATE|SLIDE 起点 终点 样本数 最小间隙。相对当前姿态，角度用度，距离与间隙用mm。\n"
L"288开门空间、289抽出空间、290工具空间：分别用 ASM_DOOR_SWEEP / ASM_TRAY_SWEEP / ASM_TOOL_SWEEP A 移动件ID 障碍件ID AXIS:名称 终点 样本数 最小间隙。由当前姿态到指定角度或直线行程；工具用已建的工具包络零件实例。每次比较一对组件，样本数2–25，离散结果只覆盖实际采样姿态。无阻碍的采样不能声称全程连续无干涉。\n"
L"\n第291–300项装配布局与尺寸联动。A 是活动顶层装配。以 CREO_OP 开头，使用实际模型和参照。291–297 为 CURRENT，298–300 为 READ。给全参数时直接发目标协议，缺真实ID或参照再查装配树。\n"
L"291 建立总装安装基准：ASM_LAYOUT_DATUM A 前缀 CSYS:总装坐标系 两个过原点且平行于Z的正交面 Z零位面 Z偏移mm。基于总装坐标系及三基准面建立安装原点、安装面和中心轴。\n"
L"292 创建空间包络：ASM_LAYOUT_ENVELOPE A 新零件名 SPACE|KEEPOUT X Y Z 长 宽 高。建立用于空间预留或禁入的矩形构造主体。\n"
L"293 建立骨架布局：ASM_LAYOUT_SKELETON A 新骨架名 宽 深 高。创建 Creo 原生骨架，集中管理宽、深、高、安装面和孔位。\n"
L"294 从骨架驱动组件定位：ASM_LAYOUT_LINK A 骨架ID 待定位组件ID CSYS:骨架定位站 CSYS:零件接口。用 Creo 坐标系重合约束把组件联到骨架定位站。\n"
L"295 建立模块安装接口：ASM_LAYOUT_INTERFACE A 模块ID 前缀 CSYS:本地坐标系 两个轴定位面 本地Z零位面 X孔距 Y孔距 Z偏移。在模块创建安装面、中心轴、接口原点及矩形四孔位基准点。\n"
L"296 复制公共安装参照：ASM_LAYOUT_COPY A ROOT或源ID 目标ID 特征名 参照1 [参照2 ...]。按当前装配位置把指定基准和单段直线轮廓复制为目标模型的本地参照。\n"
L"297 修改总装控制尺寸并核对联动：ASM_LAYOUT_DIM A ROOT或骨架ID 尺寸符号 旧值mm 新值mm。核对线性尺寸旧值，修改后列出实际联动的组件。\n"
L"298 检测跨零件外部参照：ASM_LAYOUT_REFS A ALL|ROOT|组件ID。读取组件使用的外部模型、源特征及状态。\n"
L"299 检查循环引用和断链：ASM_LAYOUT_AUDIT A ALL|ROOT|组件ID。分析可读取的外部引用图，报告循环成员、断链或无法确认项。\n"
L"300 对比两版装配布局：ASM_LAYOUT_COMPARE A 旧版装配名 CSYS:接口名或NONE 位置公差mm。按实例路径比较两个装配的组件、位姿和指定的局部接口。\n"
L"301 装配切除：ASM_FIELD_CUT A 名称 根装配闭合草绘名 POS|NEG|BOTH 深度mm或0 目标ID...。0 表示贯穿指定实例。\n"
L"302 装配通孔：ASM_FIELD_HOLE A 名称 PLANE:草绘面 PLANE:定向面 POS|NEG|BOTH X Y Z 直径 目标ID...。中心为总装XYZ毫米坐标。\n"
L"303 装配孔组：ASM_FIELD_GRID A 名称 PLANE:草绘面 PLANE:定向面 POS|NEG|BOTH 首孔X Y Z 直径 NX NY DX DY 目标ID...。节距沿草绘平面两个本地轴，最多16孔。\n"
L"304 传递孔位：ASM_FIELD_TRANSFER A 名称 PLANE:目标草绘面 PLANE:定向面 POS|NEG|BOTH 源实例ID SURFACE:内圆柱面 目标直径或0 目标ID...。使用源孔真实轴线，0 继承直径，目标面垂直孔轴。\n"
L"305 分层孔型：ASM_FIELD_LAYERS A 名称 PLANE:定向面 POS|NEG 同轴线上X Y Z （目标ID PLANE:该层起始面 THROUGH|CORE|CBORE 主直径 附加直径或0 深度或0）...。最多三层。THROUGH 附加直径与深度均为0。CORE 仅加工螺纹底孔，不创建螺纹，0为贯穿。CBORE 以主直径贯穿，再以更大的附加直径和指定深度加工沉孔。\n"
L"306 避让窗口：ASM_FIELD_WINDOW A 名称 PLANE:目标草绘面 PLANE:定向面 POS|NEG|BOTH 外形源ID 每侧间隙mm 目标ID...。将实际组件包络投影为矩形，贯穿目标。\n"
L"307 过线孔：ASM_FIELD_ROUTE A 名称 PLANE:目标草绘面 PLANE:定向面 POS|NEG|BOTH CURVE:根装配直线路径 过线孔直径 目标ID...。从真实直线路径与目标面的垂直交点定位。\n"
L"301–307 使用毫米制和主表示，只在当前顶层装配对目标实例去料；相同零件的其他实例不会自动纳入。POS 为 BWTL 原生正向（标准 ASM_FRONT 指向总装 +Z），不明确方向的贯穿操作可用 BOTH。先从当前装配读取实际实例路径和参照，原生回执可用 310 核对。\n"
L"308 按组件间隙生成垫片：ASM_FIELD_SHIM A 新零件名 下侧组件ID SURFACE:下侧面 上侧组件ID SURFACE:上侧面 CSYS:总装坐标系 中心X 中心Y 长 宽。两面须沿 +Z 相向，为坐标系对齐的无孔矩形实体面；垫片厚度取实测间隙。创建新零件并固定，未保存。\n"
L"309 生成装配定位标记：ASM_FIELD_MARK A 组件ID 标记名 CSYS:零件坐标系 X1 Y1 Z1 X2 Y2 Z2。当前装配中仅出现一次的直接零件可写入基准直线；使用零件坐标系毫米坐标，未保存。\n"
L"310 核对装配加工影响范围：ASM_FIELD_AUDIT A 顶层加工特征名。读取 Creo 相交记录和可见层级，列出同模型其他实例及扫描缺口。\n"
L"311 装配重生成诊断：ASM_Q_REGEN A。读取顶层及活动实例的当前重生成状态、失败特征和实例路径。\n"
L"312 区域间隙规则：ASM_Q_GAPS A (SCREEN|GLASS|PCB|ENCLOSURE 组件ID 组件ID 最小间隙mm)...。每组是显式指定的规则。\n"
L"313 干涉白名单：ASM_Q_INTERF A [组件ID 组件ID 允许最大干涉mm³]...。检查最多16个活动实体零件，无白名单参数时逐对检查异常；只能按用户给出的实例与上限放行。\n"
L"314 紧固孔对位：ASM_Q_HOLES A 组件ID SURFACE:首孔内圆柱面 组件ID SURFACE:次孔内圆柱面 最大偏心mm 最大夹角度。偏心在首孔中截面测量。\n"
L"315 面板齐平：ASM_Q_FLUSH A 组件ID SURFACE:实体平面 组件ID SURFACE:实体平面 最大段差mm 最大夹角度。比较两块实体面的实际范围。\n"
L"316 安装面共面：ASM_Q_COPLANE A 最大偏差mm 最大夹角度 (组件ID SURFACE:实体平面)...，至少三面，第一面作为基准。\n"
L"317 公差叠加：ASM_Q_STACK A 最小允许值mm 最大允许值mm (ADD|SUB 尺寸项名 名义尺寸 下偏差量 上偏差量)...。偏差量输入非负，按指定链做最坏情况计算。\n"
L"318 重心与支撑：ASM_Q_SUPPORT A CSYS:支撑坐标系 最小内侧裕量mm X1 Y1 X2 Y2 X3 Y3 ...。以坐标系 XY 为支撑面，输入按周向排列的3–12个凸多边形顶点，使用Creo当前密度。\n"
L"319 安装空间：ASM_Q_SPACE A CSYS:空间坐标系 Xmin Ymin Zmin Xmax Ymax Zmax [组件ID...]。实测各实体的投影范围、列出超界方向和数值。省略目标时检查活动实体。\n"
L"320 装配检查报告：ASM_Q_REPORT A [新报告目录名]。先运行用户要求的检查，再汇总当前装配的已有记录；标注未检查及未核实项。仅在用户要求导出文件时给目录名，输出工作目录下 report.txt，目录不能重名。\n"
L"321–330 装配视图与产品配置。A 是当前顶层装配名，直接组件使用 ID:编号。以下视图操作及替换不自动保存。\n"
L"321 ASM_V_REP A 名称 ID:组件... 建立并核对原生简化表示，保留列出的模块；可用 322 激活。\n"
L"322 ASM_V_ISOLATE A 名称 ID:组件... 隔离模块；ASM_V_ISOLATE A APPLY 名称 恢复已建表示；ASM_V_ISOLATE A MASTER 切回主表示。随后才能进行需主表示的操作。\n"
L"323 ASM_V_VIEW A 视角名 SAVE|APPLY 记录当前朝向或恢复命名视角。324 ASM_V_SECTION A 剖切名 PLANE:顶层平面 偏距mm；ASM_V_SECTION A 剖切名 APPLY 重用剖切。\n"
L"325 ASM_V_EXPLODE A 名称 (ID:组件 X Y Z)... 按给定的装配坐标位移毫米建立爆炸状态；ASM_V_EXPLODE A 名称 APPLY 重用；ASM_V_EXPLODE A RESET 恢复。\n"
L"326 ASM_V_SEQUENCE A 新目录 ID:组件... 按指定顺序生成 XY 包络示意图 sequence.svg。\n"
L"327 ASM_V_CONFIG A 新目录 (配置名 ID:组件 旧零件 新零件 CSYS:接口)... 最多5条；同名配置的规则会同时应用。表保存在 config.txt，必须从实际组件树及模型文件确认型号和同名安装坐标系。\n"
L"328 ASM_V_APPLY A 配置表目录 配置名 核对接口与定位后替换，未保存。329 ASM_V_COMPARE A 另一装配 CSYS:接口|NONE 位移公差mm，对比两个不同名的实际装配。\n"
L"330 ASM_V_ORDER A 配置表目录 配置名 新装配名 新输出目录 创建并保存独立订单装配，复用已有组件文件，保持原模板。\n"
L"331–340 装配BOM与交付。A 是当前顶层装配，输出目录是当前 Creo 工作目录下全新的单个目录名。这些命令不保存源模型。\n"
L"331 ASM_B_TREE A 新目录 导出分层BOM。332 ASM_B_BUY A 新目录 按自制、外购、标准件和待分类汇总。\n"
L"333 ASM_B_DIFF A 新目录 另一版装配名，对比两个不同名的实际装配。334 ASM_B_CHECK A [新目录] 检查料号、图号、材料和规格。仅在用户要求导出时给目录。\n"
L"335 ASM_B_FAST A 新目录 紧固件用量。336 ASM_B_WIRE A 新目录 线束与附件安装表。337 ASM_B_SPARE A 新目录 维修备件。只使用已在模型或实例明确标注的属性。\n"
L"338 ASM_B_ROUTE A 新目录 ID:实例... 按明确的装配顺序生成工序卡，含位置、紧固要求和检查点；未标注时不猜测数值。允许嵌套实例路径。\n"
L"339 ASM_B_NATIVE A 新目录，收集可核实的已保存原生依赖，并标出缺项。340 ASM_B_PACK A 新目录 装配图.pdf 检查报告.txt，使用当前已保存的实际配置和用户指定的工作目录直下的文件；依赖未核实就不发布。不得编造图纸、报告或配置名称。\n"
L"骨架定位站为 CSYS:BWTL_WIDTH、CSYS:BWTL_DEPTH、CSYS:BWTL_HEIGHT；对应驱动尺寸为 BW_WIDTH、BW_DEPTH、BW_HEIGHT。294 对直接且尚未约束的普通零件生效。296 可用 PLANE、AXIS、POINT、CSYS 和单段直线 CURVE，目标只能有一个实例。复制是一次性的，勿声称源参照后续更新会同步。300 旧版需以不同的模型名加载或放在当前目录，对比按实例路径和给定位置公差。\n"
L"\n装配专项检查。A=当前顶层装配，以下是检查当前模型的只读 CREO_OP。所有实例及面号来自本轮实际读取。先用 ASM_TREE 或 ASM_REFS 查找缺失的实例或面号，读到参照后继续检查。mm 和度。输入缺失时询问，供货商、公司工艺、参考方向和物理尺寸不可编造。\n"
L"ASM_W_FIND A 型号片段|ALL [+X|-X|+Y|-Y|+Z|-Z 第几个 判重公差mm]。左边第二件在确认总装坐标与视角后可按 +X 升序找第二件。\n"
L"ASM_W_PAIRS A ID:实例A ID:实例B 最大距离mm 最大夹角°；只列当前接近的平面和同轴候选。\n"
L"ASM_W_ORIENTATION A ID:实例 CSYS:组件坐标系 组件有符号轴 总装有符号轴 最大偏角；ASM_W_FANS A 总装有符号轴 最大偏角 (ID:风扇 CSYS:风扇坐标系 局部出风有符号轴)...。\n"
L"ASM_W_CONFLICT A ID:实例 检查同对放置约束；ASM_W_FREEDOM A ID:实例 查看自由度；ASM_W_OCCURRENCE A ID:层级路径 查看每层及实际位姿。\n"
L"ASM_W_SCREW_LENGTH A ID:件1 SURFACE:夹层首面 ID:件2 SURFACE:夹层末面 最少伸入 最大伸入 (型号 长度)...；候选应已核对螺纹和头型。\n"
L"ASM_W_BLIND_BOTTOM A 两对组件路径和实体面 承压面至尖端长度 有效螺纹深度 可插深度 最小啮合 最小孔底余量；ASM_W_COUNTERSINK A 两对组件路径和实体面 沉孔夹角 头部夹角 齐平公差 角度公差。\n"
L"ASM_W_PRESS_FIT A 两对同件路径和板侧面 SURFACE:孔壁 最小板厚 最大板厚 最小孔径 最大孔径 背面可用 [最小外边距 所需背面净空]，提供后两项则一并实测直线外边距并比较背面条件。\n"
L"ASM_W_RIVET_GRIP A 两对组件路径和实体面 最小夹层 最大夹层 已知背面可用空间 所需成形空间。\n"
L"ASM_W_THERMAL_GAP A ID:玻璃 ID:框 CSYS:框坐标系 左壁 右壁 下壁 上壁 玻璃膨胀ppm 框膨胀ppm 温差°C 最小间隙 约束中心X Y。四壁用实际内侧 SURFACE，窗口矩形。\n"
L"ASM_W_DOOR_GAP A 最小门缝 最大门缝 最大差 (ID:首件 相向侧面 ID:另一件 相向侧面)...。ASM_W_DRAIN A ID:底板 底部实体平面 ID:排水口 排水口最低边所在实体平面 CSYS:总装重力基准 最大高差。该坐标系 +Z 朝上。\n"
L"ASM_W_REVISIONS A (批准料号 版本)...，用Creo料号和版本属性定位混版。ASM_W_ASBUILT A 两对组件路径和实体面 样机实测 图纸名义 下偏差绝对值 上偏差。\n"
L"\n装配定位恢复仅在要求修改明确时使用 BWTL_INTENT CURRENT。ASM_W_ALIGN A 最大移动mm 最大旋转° ID:未约束直接组件 CSYS:总装主参照 CSYS:组件主参照 CSYS:总装备选 CSYS:组件备选。同一装配上使用用户指定或实际确认的两组等效参照。ASM_W_ALIGN_BATCH 用同一语法可追加多个站位。失败只在证明前一尝试未改动时换参照。已完成站位按实际约束和位姿跳过。回执写明各站位和未保存状态。检视时可用 ASM_W_CHECKPOINT A CAPTURE|COMPARE；ASM_W_RESULT A 查看最后一次站位汇总。\n"
L"\n装配量测，毫米和度。ASM_W_SQUARE A 位置公差 角度公差 (ROOT|ID:组件 CSYS:角点) 四组，按顺时针或逆时针。ASM_W_TWIST A ROOT|ID CSYS:基座 ROOT|ID CSYS:模块 目标局部X Y Z 允许偏移 允许旋转。\n"
L"ASM_W_LEVEL A CSYS:总装重力基准 (ID:脚 SURFACE:脚底面 实测地面标高 最大双向调节 现有有效旋入 最小旋入)...。ASM_W_ANCHORS A CSYS:总装基准 残差公差 (ROOT|ID:组件 CSYS:孔中心 现场X Y)...，至少两组明确对应。\n"
L"ASM_W_WIRE_LENGTH A 起点余量 终点余量 检修余量 端点连续公差 (ROOT|ID CURVE:实际中心线特征)...。ASM_W_WIRE_BEND A 最小弯曲半径 (ROOT|ID CURVE:实际中心线特征)...。只能对单段直线和圆弧报告段内半径，转折点和样条未核实。\n"
L"ASM_W_CHANNEL_FILL A ID:线槽 CSYS:槽坐标系 SURFACE:左内壁 SURFACE:右内壁 SURFACE:下内壁 SURFACE:上内壁 盖板占高 最大填充百分比 (线外径 数量)...，计算几何截面积及最大单根线径。\n"
L"\nASM_W_DISPLAY_VIEW A ID:框 CSYS:框 SURFACE:左 SURFACE:右 SURFACE:下 SURFACE:上 ID:显示面所属件 SURFACE:矩形显示面 X斜视° Y斜视°。0 为正视，面必须在窗口后。\n"
L"ASM_W_BYPASS A 同样的窗框实例/坐标系/四壁 ID:滤网 SURFACE:矩形封边面 最大缝隙mm。ASM_W_AIRFLOW A 同样的风道实例/坐标系/四壁 局部深度Z 最小截面积mm² [障碍ID]...，当前精确量测轴对齐实心方盒。\n"
L"ASM_W_VOLTAGE_ZONE A ID:高压组件 ID:低压组件 最小空气间隙 [ID:隔板 SURFACE:隔板面]。ASM_W_RAIN_COVER A CSYS:重力基准 ID:罩 SURFACE:水平罩面 ID:待遮挡件 SURFACE:待遮挡面 向-X +X -Y +Y 最低外伸。\n"
L"ASM_W_SEAL_LOOP A ID:固定件 SURFACE:密封面 ID:门板 SURFACE:压合面 胶条自由厚度 最低压缩% 最高压缩% 最大接头距离 (EDGE:直边)... 按环线顺序至少三段。\n"
L"\nASM_W_SLOT_RULE A 用 BWTL_SLOT 验同父装配内重复位置。ASM_W_REQUIRED A ROOT|ID:子装配 (触发料号 必配料号 每件所需数量)...。ASM_W_TERMINALS A ROOT|ID:端子子装配 (BWTL_KIND 的附件类别 所需数量)...。\n"
L"ASM_W_TORQUE A (ID:紧固点 工艺扭矩N·m 允许差 防松方式 标记要求)...，与 BWTL_TORQUE、BWTL_LOCKING、BWTL_TORQUE_MARK 对照。\n"
L"ASM_W_PRODUCTION_BOM A (生产料号 数量)...，只对照料号和数量。ASM_W_TEMPORARY A 读取模型或实例的 BWTL_BUILD_STATUS 与 BWTL_BUILD_NOTE。ASM_W_ISSUE_LIST A 工位|ALL [新目录]，用 BWTL_STATION 汇总工位。用户明确要导出时才给新目录。\n"
L"\nASM_W_SHARED_MODELS A ID:目标 [其他装配名]...，核对给出的订单范围。ASM_W_RAIL_CAPACITY A CSYS:根 X下 X上 Y下 Y上 Z下 Z上 模块宽 节距 [障碍实例]...。\n"
L"ASM_W_FASTENER_SIDE A ID:板 SURFACE:实际孔壁 SURFACE:选中安装面 ID:螺钉 SURFACE:实际杆面 SURFACE:螺钉承压面 最大偏心 最大座面段差。ASM_W_MIXED_SCREWS A ROOT|ID:子装配 邻近距离，读 FASTENER、SPEC、BWTL_LENGTH。\n"
L"ASM_W_ELECTRIC_LAYOUT A CSYS:根 X下 Y下 X上 Y上 最小间距 (ID:模块 CSYS:组件 端子有符号XY轴)...。这是测量后的排布建议，留空拒绝虚填。ASM_W_INSTALL_ORDER A 组件数 ID:直接组件... [ID:前置 ID:后置]...，原生直接父特征加给定顺序。\n"
L"ASM_W_TRANSPORT A ROOT|ID:组件 CSYS:根 操作单边余量 包装X Y Z (STRAIGHT_X|STRAIGHT_Y|TURN 可用X Y Z)...。TURN 为矩形固定中心原地转向。ASM_W_REWORK A 不同名同源旧装配 允许位移 允许角度 [全新输出目录]。依据实例路径，不自动配对不同ID。\n"
L"ASM_W_METHOD_RECORD A ID:刚验收实例 案例类别，把成功参照和首试错误保存在该 BWTL 实例的案例文件。ASM_W_METHOD_RECALL A ID:新任务实例 案例类别，读取并核对历史参照在本次的可用性。仅在用户明确使用装配专项检查中保存的案例类别时用 RECALL。若请求附有「装配学习案例」节，则按该节的原生定位关系，用 ASM_CSYS 等命令；两类案例文件独立。\n"
L"\n装配检修几何检查只用实际组件和在模型里已做出的工具、手、弯线等包络。以下语法以 CREO_OP 开头：命令 A 最小间隙mm (阶段 ID:移动件 ID:障碍 AXIS:移动件轴 ROTATE|SLIDE 起值 终值 样本数2–25)...。旋转度，平移mm。仅知单个阶段时按现有单段扫掠检查。依次按任务提供角色。\n"
L"ASM_W_TOOL_ACCESS 阶段 STRAIGHT、ANGLED 为 SLIDE，SWING 为 ROTATE。ASM_W_DOOR_FINAL 阶段 CLOSE，ROTATE，最后不超过45度。ASM_W_TERMINAL_ACCESS 在最小间隙和阶段之间加 计划剥线mm 可用直进深度mm 规定最低剥线mm；阶段 WIRE、TOOL。ASM_W_PLUG_PATH 阶段 PLUG、RELEASE、CABLE，分别提供插头、释放和弯线包络。\n"
L"ASM_W_RAIL_SERVICE 阶段 SLIDE、可选 RELEASE；ASM_W_SMALL_SERVICE 阶段 GRIP、REMOVE；ASM_W_FILTER_SERVICE 阶段 DRAW、GRIP。ASM_W_INSTALL_PATH 使用同一件，阶段 ENTRY、可选 TURN、SEAT，起始须 0，下一阶段会接到上一阶段终点。每一阶段要明确待检查障碍，命令按独立装配采样，不假设连续运动毫无碰撞。\n"
L"\nASM_W_DOOR_SHIM A 目标间距 垫片厚度阶梯或0 最大允许垫片 (ID:站位1 SURFACE:面 ID:对侧 SURFACE:对面)...，实测并计算。ASM_W_DOOR_WIRE A ROOT|ID CSYS:固定线端 ID:门 CSYS:门侧线端 AXIS:门轴 起角 终角 可动线长 最小余量 样本数，核对端点理论最小长度。\n"
L"ASM_W_EDGE_WIRE A ROOT|ID CURVE:实际直线段 ID:板 EDGE:实际直板边 外径 最小余量。ASM_W_WIRE_CROSS A ROOT|ID CURVE:强电直线 ROOT|ID CURVE:弱电直线 两个外径 最小余量 最大平行长度 最小交叉角。\n"
L"ASM_W_CONNECTIONS A (ID:路径@CSYS:端口 ID:路径@CSYS:另一端口)...。线束标 BWTL_KIND=HARNESS 和 BWTL_WIRE_FROM / BWTL_WIRE_TO，端口须为真实坐标系。\n"
L"ASM_W_WELD_CONFLICT A (ID:实际焊缝实体包络 ID:后装件 最大允许相交体积mm³)...。ASM_W_WELD_TOOL 使用运动阶段 WELD 与 GRIND 语法，分别指定已建的工具包络与对应障碍。ASM_W_HIGHLIGHT A ID:报告中实例 [SURFACE:报告中的面] 或 CLEAR，暂时高亮指定项。\n"
L"\nASM_W_INTERFACE A ID:模块 CSYS:实际接口 SURFACE:安装面 名义Z 允许Z误差 允许倾斜° (SURFACE:孔 名义X Y 最大孔位偏差 最大轴偏角)...。ASM_W_CHANGE_PREVIEW A ROOT|ID:控制模型 实际驱动尺寸符号 拟改值mm，读取影响候选。\n"
L"ASM_W_BEAM_LAYOUT A CSYS:总装 X下 X上 端边距 最大节距 PREVIEW|APPLY ID:同型号横梁...；ASM_W_TRAY_LAYOUT 类似但用 Z下 Z上、目标层数。调整或新增零件需明确执行；不自动减件。ASM_W_INTERFACE_DRAW A 新目录 CSYS:总装 (标签 ROOT|ID CSYS:接口)...，输出示意和实际 XYZ。ASM_W_ORDER_AUDIT A 工作目录下的指定CSV。\n"
L"ASM_W_DROP_FASTENER / ASM_W_LABEL_VIEW / ASM_W_WATER_PATH / ASM_W_RELEASE_DROP A ROOT|ID CSYS:起点 有符号方向 最大距离 ID:实体障碍...，分别按松脱、视线、滴水和释放的指定方向查首个原生交点。\n"
L"ASM_W_GLASS_CORNER A ID:窗框 CSYS:框 SURFACE:窗口所在平面 EDGE:窗内边 ID:玻璃 SURFACE:板面 EDGE:玻璃外边 轮廓总公差 最小余量；形状应为矩形或四角等半径圆角矩形。ASM_W_GLUE_SPACE A 最小净宽 最小深 胶嘴直径 (两对测宽组件面 两对测深组件面)...。ASM_W_GLASS_PRESSURE A ID:禁压区实体 最低留空 ID:周边件...。\n"
L"ASM_W_HEAT_ZONE A ID:电源 SURFACE:散热面 留空深度 平面外扩 ID:障碍...。ASM_W_AIR_PAIR A ROOT|ID:排 CSYS:排 有符号排风轴 ROOT|ID:进 CSYS:进 有符号端口外向轴 距离阈值 方向半角。\n"
L"用户明确建线或安装线夹时才写，均未保存。ASM_W_ROUTE_WRITE A 路径命名前缀 CSYS:总装 外径 净空 ROOT|ID:起点 CSYS:起点 ROOT|ID:终点 CSYS:终点 可用区X下 Y下 Z下 X上 Y上 Z上 [最多4个障碍ID]。创建台阶正交基准曲线，圆顺与实际线材另行核对。ASM_W_CLIP_WRITE A 已有线夹模型 CSYS:线夹安装 ROOT|ID CURVE:直线 CSYS:总装 首距 节距 最小端距 数量 NONE|ID:需检查干涉的障碍，线夹坐标系 X 沿线。\n"
L"\nASM_W_GLASS_BLOCKS A ID:玻璃 CSYS:玻璃 标准垫块名 CSYS:垫块承压 支点占宽百分比 承压留空mm 最小端距mm BOTTOM|SIDES。玻璃坐标系 X 向宽，Y 朝上，Z 为厚度；垫块取实测最大 Y 端为承压面。直接安装需明确执行，留在会话，未保存。\n"
L"ASM_W_DOOR_HAND A 备用装配名 CSYS:备用总装 LEFT|RIGHT 门中线X 最小离中线 (HINGE|LATCH|LIMIT|WIRE ROOT|ID CSYS:接口 L|R)...。四种明确角色都要给，L/R 供出线侧，其他角色按开向判断。ASM_W_GROUND_BOND A ID:接地柱 SURFACE:实际杆面 SURFACE:承压面 ID:线鼻 SURFACE:环孔 SURFACE:贴合面 最大间隙，读取 BWTL_GROUND_PATH。\n"
L"ASM_W_CONNECTOR_OPENING A ID:开口件 CSYS:框 四个实面(左/右/下/上) ID:插头 X|Y|Z 斜穿旋转角 最小单边余量。ASM_W_POSTURE A CSYS:重力基准 X|Y|Z 翻转角 最小稳定裕量 (新支撑平面X Y)...，用实际质量重心和凸支撑轮廓。\n"
L"ASM_W_REASSEMBLE A ID:组件 CSYS:防呆 ROOT|ID:安装方 CSYS:期望接口 位置误差 角度误差。ASM_W_WORKPOINTS A ID:实例... 按给定工序顺序输出实际位置和工艺。ASM_W_REMOVAL_DRAW A 新目录 CSYS:基准 (ID:拆卸部件 有符号移出轴 ID:紧固件|NONE ID:路径@CSYS:端口|NONE)...，从实际模型输出分步示意图。\n"
L"ASM_W_ROOM_CLEARANCE A ROOT|ID:机柜 CSYS:基准 -X边 +X边 -Y边 +Y边 -Z边 +Z边 六向规定最小净空（同序）。ASM_W_HANDLING A CSYS:总装 ROOT|ID CSYS:吊点 ROOT|ID CSYS:首叉孔 ROOT|ID CSYS:次叉孔 最大重心偏差 最小叉距 最大叉距 中心线检查长度 [障碍ID]...。只查实际几何及重心，不用几何保证承载。\n"
L"ASM_W_ORDER_IMPACT A ID:变更目标 订单装配名...，按实际料号或同名模型查订单、图号和工位。ASM_W_PRE_RELEASE A OUTDOOR|INDOOR|CONTROL CSYS:总装 允许最大X Y Z，以有 BWTL_KIND 标注的组件、原生再生状态和实际外廓预检。\n"
L"下列沿用装配运动8字段语法：ASM_W_OUTDOOR_ACCESS 阶段 INSTALL、REMOVE。ASM_W_CLOSE_BLOCKS 阶段 OPEN、CLOSED 对比同一路径开盖和封盖状态。ASM_W_TEMP_SUPPORT 阶段 SUPPORT、CLAMP、HAND。ASM_W_REMOVE_MIN 阶段 BLOCK，可列若干同移动件、同轴和范围的不同障碍。ASM_W_CASTER_BRAKE 阶段 SWIVEL 与 BRAKE，SWIVEL 用完整一周旋转范围。只按实际包络采样。\n";
#endif
